cat > /tmp/restore.php <<'EOF'
<?php
$snap = json_decode(file_get_contents($argv[1]), true);
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$pdo->beginTransaction();
$pdo->exec('DELETE FROM purchase_line');
$pdo->exec('DELETE FROM purchase');
$cols = fn(array $row) => array_keys($row);
foreach ($snap['purchase'] as $row) {
  $c = $cols($row);
  $sql = 'INSERT INTO purchase ('.implode(',', $c).') VALUES ('.implode(',', array_fill(0, count($c), '?')).')';
  $pdo->prepare($sql)->execute(array_values($row));
}
foreach ($snap['purchase_line'] as $row) {
  $c = $cols($row);
  $sql = 'INSERT INTO purchase_line ('.implode(',', $c).') VALUES ('.implode(',', array_fill(0, count($c), '?')).')';
  $pdo->prepare($sql)->execute(array_values($row));
}
foreach ($snap['book'] as $row) {
  $id = $row['id']; unset($row['id']);
  $set = implode(', ', array_map(fn($k) => "$k = ?", array_keys($row)));
  $pdo->prepare("UPDATE book SET $set WHERE id = ?")->execute([...array_values($row), $id]);
}
foreach (['book' => 'book_id_seq', 'purchase' => 'purchase_id_seq', 'purchase_line' => 'purchase_line_id_seq'] as $t => $seq) {
  $s = $snap['seq'][$seq];
  $pdo->query(sprintf("SELECT setval('%s', %d, %s)", $seq, (int)$s['last_value'], $s['is_called'] ? 'true' : 'false'));
}
$pdo->commit();
echo "restored\n";
EOF
cat > /tmp/verify.php <<'EOF'
<?php
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$snap = json_decode(file_get_contents($argv[1]), true);
$now = [];
foreach (['book','purchase','purchase_line'] as $t) $now[$t] = $pdo->query("SELECT * FROM $t ORDER BY id")->fetchAll(PDO::FETCH_ASSOC);
foreach (['book_id_seq','purchase_id_seq','purchase_line_id_seq'] as $s) $now['seq'][$s] = $pdo->query("SELECT last_value, is_called FROM $s")->fetch(PDO::FETCH_ASSOC);
$norm = fn($x) => json_decode(json_encode($x), true);
foreach (['book','purchase','purchase_line'] as $t) echo $t, ': ', ($norm($snap[$t]) == $norm($now[$t]) ? 'MATCH' : 'DIFF'), "\n";
echo 'sequences: ', (json_encode($snap['seq']) === json_encode($now['seq']) ? 'MATCH' : 'DIFF '.json_encode($now['seq'])), "\n";
EOF
php /tmp/restore.php /tmp/bookshop-backup/before.json && php /tmp/verify.php /tmp/bookshop-backup/before.json

